s=s.replace("""  /** The retire-from date typed on each person's row. */""","""  /** The sort keys the list can be shown in. */
  protected readonly sortKeys = SORT_KEYS;
  /** How this user's screen orders the list; only what is shown, never the stored positions. */
  protected readonly sortBy = signal<SortKey>('added');
  /** The people shown, in the chosen order; equal keys keep list order (the sort is stable). */
  protected readonly sorted = computed(() => {
    const list = this.shown();
    switch (this.sortBy()) {
      case 'name':
        return [...list].sort((a, b) => nameKey(a.name).localeCompare(nameKey(b.name)));
      case 'grade':
        return [...list].sort((a, b) => this.gradeToday(a).localeCompare(this.gradeToday(b)));
      case 'due-total': {
        const due = new Map(list.map((p) => [p.id, this.dueCents(p)]));
        return [...list].sort((a, b) => {
          const x = due.get(a.id) ?? null;
          const y = due.get(b.id) ?? null;
          if (x === null || y === null) return (x === null ? 1 : 0) - (y === null ? 1 : 0);
          return x < y ? -1 : x > y ? 1 : 0;
        });
      }
      default:
        return list;
    }
  });
  /** The retire-from date typed on each person's row. */""",1)
