    this.sortBy.set((SORT_KEYS as readonly string[]).includes(key) ? (key as SortKey) : 'added');
  }

  protected gradeToday(p: Person): string {""",1)
s=s.replace("""// The people on the sheet""","""const SORT_KEYS = ['added', 'name', 'grade', 'due-total'] as const;
type SortKey = (typeof SORT_KEYS)[number];

/** A name as names are compared: trimmed, ignoring case. */
function nameKey(name: string): string {
  return name.trim().toLowerCase();
}

// The people on the sheet""",1)
open(p,'w').write(s)
